<script lang="ts">
 import {languageOverrides} from "./localization";
 import {Plus,X,ArrowUp,ArrowDown,Check,Save,Eraser} from "./icons";import {translator} from './i18n';import ReportFilter from './ReportFilter.svelte';import type {ReportSettingsRequest} from './report-settings';
 export let request:ReportSettingsRequest;export let language:'ru'|'ro'|"en";export let onclose:()=>void;
 let tab:'filter'|'sort'='filter',filters=structuredClone(request.filters),sort=structuredClone(request.sort);
 let previousRequest=request;
 $: if(request!==previousRequest){filters=structuredClone(request.filters);sort=structuredClone(request.sort);previousRequest=request;}
 $:t=translator(language,$languageOverrides);
 function move(i:number,delta:number){const j=i+delta;if(j<0||j>=sort.length)return;const copy=[...sort];[copy[i],copy[j]]=[copy[j],copy[i]];sort=copy;}
 function save(close=false){request.onapply(structuredClone(filters),structuredClone(sort));if(close)onclose();}
</script>
<div class="report-settings-editor"><nav class="settings-tabs"><button class:chosen={tab==='filter'} onclick={()=>tab='filter'}>{t('Отбор','Filtrare')}</button><button class:chosen={tab==='sort'} onclick={()=>tab='sort'}>{t('Сортировка','Sortare')}</button></nav>
{#if tab==='filter'}<div class="settings-tools"><button onclick={()=>filters=filters.map(f=>({...f,enabled:true}))}><Check size={15}/>{t('Установить все пометки','Selectează toate')}</button><button onclick={()=>filters=filters.map(f=>({...f,enabled:false}))}><X size={15}/>{t('Снять все пометки','Deselectează toate')}</button><button onclick={()=>filters=filters.map(f=>({...f,enabled:f.values.length>0}))}>{t('Отметить заполненные поля','Selectează câmpurile completate')}</button></div><div class="filter-head"><strong>{t('Поле','Câmp')}</strong><strong>{t('Тип сравнения','Tip comparație')}</strong><strong>{t('Значение','Valoare')}</strong></div>{#each filters as filter,i}<ReportFilter {language} label={request.labels[i]} items={request.items[i]||[]} bind:filter={filters[i]}/>{/each}
{:else}<div class="settings-tools"><button onclick={()=>sort=[...sort,{column:0,descending:false}]}><Plus size={16}/>{t('Добавить','Adaugă')}</button><button onclick={()=>sort=[]}><Eraser size={16}/>{t('Очистить','Golește')}</button></div><table><thead><tr><th>{t('Поле','Câmp')}</th><th>{t('Направление сортировки','Direcția sortării')}</th><th></th></tr></thead><tbody>{#each sort as rule,i}<tr><td><select bind:value={rule.column}>{#each request.columns as column,index}<option value={index}>{column}</option>{/each}</select></td><td><select bind:value={rule.descending}><option value={false}>{t('По возрастанию','Crescător')}</option><option value={true}>{t('По убыванию','Descrescător')}</option></select></td><td class="sort-actions"><button aria-label={t('Выше','Mai sus')} onclick={()=>move(i,-1)}><ArrowUp size={15}/></button><button aria-label={t('Ниже','Mai jos')} onclick={()=>move(i,1)}><ArrowDown size={15}/></button><button aria-label={t('Удалить правило','Elimină regula')} onclick={()=>sort=sort.filter((_,j)=>j!==i)}><X size={15}/></button></td></tr>{/each}</tbody></table>{/if}
<footer><button class="button secondary" onclick={()=>save(true)}><Check size={16}/>OK</button><button class="button secondary" onclick={()=>save()}><Save size={16}/>{t('Сохранить','Salvează')}</button><button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer></div>
<style>.report-settings-editor{display:flex;flex-direction:column;gap:8px;min-height:100%;padding:12px;box-sizing:border-box}.settings-tabs,.settings-tools{display:flex;gap:6px;flex-wrap:wrap}.settings-tabs button,.settings-tools button,.sort-actions button{padding:7px 10px;background:transparent;border:0;color:var(--text);display:flex;align-items:center;gap:6px}.settings-tabs button.chosen{box-shadow:inset 0 -2px var(--accent)}.filter-head{display:grid;grid-template-columns:155px 125px minmax(0,1fr);font-size:12px;background:#80808020;padding:8px 4px}table{width:100%;border-collapse:collapse}th{text-align:left;background:#80808020}td,th{padding:6px}td select{width:100%}.sort-actions{display:flex}footer{margin-top:auto;display:flex;justify-content:flex-end;gap:8px;padding-top:18px}</style>
